//! Package prov exports the log of a change (ADR 0030) as W3C PROV-O provenance, serialized as JSON-LD (ADR 0057).
//!
//! The change is a prov:Activity, held by its unit (a prov:Organization); every journal record of its execution is
//! an activity of the change, associated with the agent that ran it under the plan of its methodology action; facts
//! and node versions are entities generated by the run that produced them, attributed to their principal, derived
//! from what they came from; reviews are activities using the version they judge; a landed version is a member of
//! the baseline it landed in. Every journal record, fact and change impact carries its log position (goap:seq) and
//! its whole record (goap:record), so the export loses nothing PROV does not model.

use std::collections::HashMap;
use std::sync::LazyLock;

use chrono::{DateTime, Utc};
use goap_domain::{
    self as domain, BaselineID, Change, ChangeID, ChangeImpact, ChangeImpactID, ChangeItem,
    ImpactEvent, ItemID, LogEntry, NodeID, NodeRef, gotime,
};
use goap_journal as journal;
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value, json};

use crate::gojson;

/// Vocab is the namespace of the GOAP terms of the export; instances are named under urn:goap:.
pub const VOCAB: &str = "https://github.com/zimwip/goap/ns/prov#";

/// MediaType is the media type of the export.
pub const MEDIA_TYPE: &str = "application/ld+json";

/// The JSON-LD context of the export.
static CONTEXT: LazyLock<Map<String, Value>> = LazyLock::new(|| {
    let v = json!({
        "prov":   "http://www.w3.org/ns/prov#",
        "xsd":    "http://www.w3.org/2001/XMLSchema#",
        "rdfs":   "http://www.w3.org/2000/01/rdf-schema#",
        "goap":   VOCAB,
        "label":  "rdfs:label",
        "record": {"@id": "goap:record", "@type": "@json"},
        "data":   {"@id": "goap:data", "@type": "@json"},
    });
    match v {
        Value::Object(m) => m,
        _ => Map::new(),
    }
});

/// Errors of an export.
#[derive(Debug, thiserror::Error)]
pub enum Error {
    /// An entry of the log could not be read.
    #[error("log entry {seq} ({entry_type}): {source}")]
    Entry {
        seq: i64,
        entry_type: String,
        #[source]
        source: serde_json::Error,
    },
}

/// Document is a JSON-LD document.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct Document {
    #[serde(rename = "@context")]
    pub context: Map<String, Value>,
    #[serde(rename = "@graph")]
    pub graph: Vec<Map<String, Value>>,
}

impl Document {
    /// The document as a JSON value.
    pub fn to_value(&self) -> Value {
        json!({
            "@context": Value::Object(self.context.clone()),
            "@graph": Value::Array(self.graph.iter().cloned().map(Value::Object).collect()),
        })
    }

    /// The document as Go's `json.Marshal` writes it.
    pub fn marshal(&self) -> String {
        gojson::marshal(&self.to_value())
    }

    /// The document as Go's `json.MarshalIndent(doc, prefix, indent)` writes it (the export of the graph service is
    /// `marshal_indent("", "  ")`).
    pub fn marshal_indent(&self, prefix: &str, indent: &str) -> String {
        gojson::marshal_indent(&self.to_value(), prefix, indent)
    }
}

fn decode<T: serde::de::DeserializeOwned>(e: &LogEntry) -> Result<T, Error> {
    serde_json::from_value(e.payload.clone()).map_err(|source| Error::Entry {
        seq: e.seq,
        entry_type: e.r#type.clone(),
        source,
    })
}

/// Export is the provenance of a change from its log entries (in the order of the log).
pub fn export(c: &Change, entries: &[LogEntry]) -> Result<Document, Error> {
    let mut b = Builder::default();
    b.change(c);
    for e in entries {
        match e.stream() {
            s if s == journal::STREAM_JOURNAL => {
                let r: journal::Record = decode(e)?;
                b.execution(c, e, &r);
            }
            s if s == domain::LOG_FACT => {
                let it: ChangeItem = decode(e)?;
                b.fact(c, e, &it);
            }
            s if s == journal::STREAM_MODEL => {
                let ex: journal::ModelExchange = decode(e)?;
                b.exchange(c, e, &ex);
            }
            s if s == domain::LOG_CHANGE => b.header(c, e),
            s if s == domain::LOG_IMPACT => {
                let ev: ImpactEvent = decode(e)?;
                b.impact(c, e, &ev);
            }
            _ => {}
        }
    }
    Ok(Document {
        context: CONTEXT.clone(),
        graph: b.graph(),
    })
}

/// url.PathEscape.
fn path_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for &c in s.as_bytes() {
        let keep = c.is_ascii_alphanumeric()
            || matches!(
                c,
                b'-' | b'_' | b'.' | b'~' | b'$' | b'&' | b'+' | b':' | b'=' | b'@'
            );
        if keep {
            out.push(c as char);
        } else {
            out.push_str(&format!("%{c:02X}"));
        }
    }
    out
}

// Names of the instances.
pub(crate) fn iri(kind: &str, id: &str) -> String {
    format!("urn:goap:{kind}:{}", path_escape(id))
}

fn change_iri(id: &ChangeID) -> String {
    iri("change", id)
}
fn run_iri(id: &str) -> String {
    iri("execution", id)
}
pub(crate) fn item_iri(id: &ItemID) -> String {
    iri("item", id)
}
pub(crate) fn impact_iri(id: &ChangeImpactID) -> String {
    iri("impact", id)
}
fn baseline_iri(id: &BaselineID) -> String {
    iri("baseline", id)
}
fn node_iri(id: &NodeID) -> String {
    iri("node", id)
}
fn version_iri(r: &NodeRef) -> String {
    format!("{}@v{}", iri("node", &r.id), r.version)
}
pub(crate) fn principal_iri(p: &str) -> String {
    iri("principal", p)
}
pub(crate) fn review_object_iri(key: &str) -> String {
    iri("review-object", key)
}

#[derive(Default)]
pub(crate) struct Builder {
    order: Vec<String>,
    pub(crate) nodes: HashMap<String, Map<String, Value>>,
    /// impacts are the change impacts as declared so far, to name what a written version revises.
    impacts: HashMap<ChangeImpactID, ChangeImpact>,
}

/// add adds a value to a property, keeping it single while it has one value and skipping duplicates.
fn add(n: &mut Map<String, Value>, prop: &str, v: Value) {
    match n.get_mut(prop) {
        None => {
            n.insert(prop.to_string(), v);
        }
        Some(Value::Array(cur)) => {
            if !cur.iter().any(|x| same(x, &v)) {
                cur.push(v);
            }
        }
        Some(cur) => {
            if !same(cur, &v) {
                let old = cur.take();
                *cur = Value::Array(vec![old, v]);
            }
        }
    }
}

fn same(a: &Value, b: &Value) -> bool {
    gojson::marshal(a) == gojson::marshal(b)
}

fn set(n: &mut Map<String, Value>, prop: &str, v: &str) {
    if !v.is_empty() {
        n.insert(prop.to_string(), Value::String(v.to_string()));
    }
}

fn r(id: &str) -> Value {
    json!({"@id": id})
}

fn at(t: &DateTime<Utc>) -> Value {
    json!({"@value": gotime::format(t), "@type": "xsd:dateTime"})
}

fn set_time(n: &mut Map<String, Value>, prop: &str, t: &DateTime<Utc>) {
    if !gotime::is_zero(t) {
        n.insert(prop.to_string(), at(t));
    }
}

fn set_time_opt(n: &mut Map<String, Value>, prop: &str, t: &Option<DateTime<Utc>>) {
    if let Some(t) = t {
        set_time(n, prop, t);
    }
}

/// entry stamps a description with its log position and whole record.
fn entry(n: &mut Map<String, Value>, e: &LogEntry) {
    add(n, "goap:seq", json!(e.seq));
    add(n, "goap:logType", json!(e.r#type));
    set(n, "goap:flow", &e.flow);
    // the id of the entry this one follows from (ADR 0105)
    set(n, "goap:causation", &e.causation);
    if !e.payload.is_null() {
        add(n, "record", e.payload.clone());
    }
}

/// by is the activity behind an entry: its action run, else the change itself.
fn by(c: &Change, execution: &str) -> String {
    if !execution.is_empty() {
        run_iri(execution)
    } else {
        change_iri(&c.id)
    }
}

fn str_of<'a>(data: &'a Map<String, Value>, k: &str) -> &'a str {
    data.get(k).and_then(Value::as_str).unwrap_or("")
}

struct Origin {
    r#ref: NodeRef,
    key: String,
}

/// origins_of reads the origins of a created event (ADR 0077): the patch is what the log stored, so its numbers and
/// lists come back from JSON.
fn origins_of(patch: &Map<String, Value>) -> Vec<Origin> {
    let mut out = Vec::new();
    let Some(Value::Array(list)) = patch.get("origins") else {
        return out;
    };
    for x in list {
        let Value::Object(m) = x else { continue };
        let id = str_of(m, "id");
        let v = match m.get("version") {
            Some(Value::Number(n)) => n
                .as_i64()
                .or_else(|| n.as_f64().map(|f| f as i64))
                .unwrap_or(0),
            _ => 0,
        };
        let key = str_of(m, "key");
        if !id.is_empty() && v > 0 {
            out.push(Origin {
                r#ref: NodeRef::new(id, v),
                key: key.to_string(),
            });
        }
    }
    out
}

impl Builder {
    fn graph(&mut self) -> Vec<Map<String, Value>> {
        self.order
            .iter()
            .map(|id| self.nodes.get(id).cloned().unwrap_or_default())
            .collect()
    }

    /// node is the description of id, created with its types on first mention; types add up. It returns the id.
    pub(crate) fn node(&mut self, id: &str, types: &[&str]) -> String {
        let n = self.nodes.entry(id.to_string()).or_insert_with(|| {
            self.order.push(id.to_string());
            let mut m = Map::new();
            m.insert("@id".into(), json!(id));
            m
        });
        for t in types {
            add(n, "@type", json!(t));
        }
        id.to_string()
    }

    /// The description of a node already named.
    fn m(&mut self, id: &str) -> &mut Map<String, Value> {
        if !self.nodes.contains_key(id) {
            self.node(id, &[]);
        }
        self.nodes.get_mut(id).expect("node")
    }

    /// principal is the agent a principal or component of the log names (empty: none).
    fn principal(&mut self, p: &str, types: &[&str]) -> String {
        if p.is_empty() {
            return String::new();
        }
        let id = principal_iri(p);
        let mut all = vec!["prov:Agent"];
        all.extend_from_slice(types);
        self.node(&id, &all);
        set(self.m(&id), "label", p);
        id
    }

    fn change(&mut self, c: &Change) {
        let n = self.node(&change_iri(&c.id), &["prov:Activity", "goap:Change"]);
        {
            let m = self.m(&n);
            set(m, "label", &c.title);
            set(m, "goap:intent", &c.intent);
            set(m, "goap:methodology", &c.methodology);
            set(m, "goap:namespace", &c.namespace);
            set(m, "goap:status", &c.status);
            set(m, "goap:project", &c.project_id);
            set(m, "goap:goal", &c.goal);
            if !c.data.is_empty() {
                m.insert("goap:data".into(), Value::Object(c.data.clone()));
            }
            set(m, "goap:branch", &c.branch);
            set_time(m, "prov:startedAtTime", &c.created_at);
            if !c.parent_id.is_empty() {
                add(m, "goap:partOf", r(&change_iri(&c.parent_id)));
            }
        }
        if !c.owner_org.is_empty() {
            let unit = iri("unit", &c.owner_org);
            self.node(&unit, &["prov:Agent", "prov:Organization"]);
            set(self.m(&unit), "label", &c.owner_org);
            add(self.m(&n), "prov:wasAssociatedWith", r(&unit));
        }
        // the state the change started from (the empty state of a namespace's first change has no baseline, ADR 0056)
        if !c.baseline_id.is_empty() {
            self.node(
                &baseline_iri(&c.baseline_id),
                &["prov:Entity", "prov:Collection", "goap:Baseline"],
            );
            add(self.m(&n), "prov:used", r(&baseline_iri(&c.baseline_id)));
        }
        if !c.result_baseline_id.is_empty() {
            let bl = self.node(
                &baseline_iri(&c.result_baseline_id),
                &["prov:Entity", "prov:Collection", "goap:Baseline"],
            );
            let m = self.m(&bl);
            add(m, "prov:wasGeneratedBy", r(&change_iri(&c.id)));
            if !c.baseline_id.is_empty() {
                add(m, "prov:wasRevisionOf", r(&baseline_iri(&c.baseline_id)));
            }
        }
    }

    /// execution is a journal record: an action run (or a scheduling or planning record) of the change.
    fn execution(&mut self, c: &Change, e: &LogEntry, rec: &journal::Record) {
        let n = self.node(&run_iri(&rec.id), &["prov:Activity", "goap:Execution"]);
        {
            let m = self.m(&n);
            entry(m, e);
            let mut label = rec.kind.clone();
            if !rec.action.is_empty() {
                label += &format!(" {}", rec.action);
            }
            set(m, "label", &label);
            set(m, "goap:kind", &rec.kind);
            set(m, "goap:process", &rec.process_id);
            set(m, "goap:action", &rec.action);
            set(m, "goap:actionKind", &rec.action_kind);
            set(m, "goap:status", &rec.status);
            set(m, "goap:activity", &rec.activity_ref);
            set(m, "goap:traceId", &rec.trace_id);
            set(m, "goap:error", &rec.error);
            add(m, "goap:partOf", r(&change_iri(&c.id)));
            set_time_opt(m, "prov:startedAtTime", &rec.started_at);
            set_time_opt(m, "prov:endedAtTime", &rec.ended_at);
        }

        // who ran it: the person deciding a human action, else the methodology agent, under the plan of the action
        let mut who = String::new();
        if !rec.actor.is_empty() {
            who = self.principal(&rec.actor, &["prov:Person"]);
        } else if !rec.agent.is_empty() {
            who = iri("agent", &format!("{}/{}", rec.methodology, rec.agent));
            self.node(
                &who,
                &["prov:Agent", "prov:SoftwareAgent", "goap:MethodologyAgent"],
            );
            let a = self.m(&who);
            set(a, "label", &rec.agent);
            set(a, "goap:planner", &rec.planner);
        }
        if !who.is_empty() {
            add(self.m(&n), "prov:wasAssociatedWith", r(&who));
            let mut assoc = Map::new();
            assoc.insert("@type".into(), json!("prov:Association"));
            assoc.insert("prov:agent".into(), r(&who));
            if !rec.action.is_empty() {
                let mut version = rec.methodology.clone();
                if !rec.methodology_version.is_empty() {
                    version += &format!("@{}", rec.methodology_version);
                }
                let plan = iri("plan", &format!("{version}#{}", rec.action));
                self.node(&plan, &["prov:Entity", "prov:Plan", "goap:Action"]);
                let p = self.m(&plan);
                set(p, "label", &rec.action);
                set(p, "goap:methodology", &rec.methodology);
                set(p, "goap:methodologyVersion", &rec.methodology_version);
                assoc.insert("prov:hadPlan".into(), r(&plan));
            }
            add(
                self.m(&n),
                "prov:qualifiedAssociation",
                Value::Object(assoc),
            );
        }
        // the models and tools it called act on its behalf
        for mc in &rec.model_calls {
            let name = format!("{}/{}", mc.provider, mc.model)
                .trim_matches('/')
                .to_string();
            if name.is_empty() {
                continue;
            }
            let id = iri("model", &name);
            self.node(&id, &["prov:Agent", "prov:SoftwareAgent", "goap:Model"]);
            set(self.m(&id), "label", &name);
            add(self.m(&n), "prov:wasAssociatedWith", r(&id));
        }
        for t in &rec.tool_calls {
            let id = iri("tool", &t.name);
            self.node(&id, &["prov:Agent", "prov:SoftwareAgent", "goap:Tool"]);
            set(self.m(&id), "label", &t.name);
            add(self.m(&n), "prov:wasAssociatedWith", r(&id));
        }
        // the node versions it started from
        for rd in &rec.reads {
            let v = self.version(rd, "", "");
            add(self.m(&n), "prov:used", r(&v));
        }
        set(self.m(&n), "goap:parentProcess", &rec.parent_process_id);
    }

    /// exchange is the request and the answer of an LLM call: an entity the action run generated, with the texts.
    fn exchange(&mut self, c: &Change, e: &LogEntry, ex: &journal::ModelExchange) {
        let n = self.node(
            &iri("exchange", &e.id),
            &["prov:Entity", "goap:ModelExchange"],
        );
        {
            let m = self.m(&n);
            entry(m, e);
            set(m, "label", &format!("model call {}", e.subject));
            set(m, "goap:system", &ex.system);
            set(m, "goap:response", &ex.response);
            if ex.truncated {
                m.insert("goap:truncated".into(), Value::Bool(true));
            }
            set_time_opt(m, "prov:generatedAtTime", &e.at);
            add(m, "prov:wasGeneratedBy", r(&by(c, &e.execution)));
        }
        let p = self.principal(&e.by, &[]);
        if !p.is_empty() {
            add(self.m(&n), "prov:wasAttributedTo", r(&p));
        }
    }

    /// header is an edit of the header of the change (title, intent, goal, status, data): an activity on the change.
    fn header(&mut self, c: &Change, e: &LogEntry) {
        let n = self.node(&iri("header", &e.id), &["prov:Activity", "goap:HeaderEdit"]);
        {
            let m = self.m(&n);
            entry(m, e);
            set(m, "label", &format!("edit {}", e.subject));
            set_time_opt(m, "prov:startedAtTime", &e.at);
            add(m, "prov:used", r(&change_iri(&c.id)));
        }
        let p = self.principal(&e.by, &[]);
        if !p.is_empty() {
            add(self.m(&n), "prov:wasAssociatedWith", r(&p));
        }
    }

    /// fact is an item of the change's blackboard.
    fn fact(&mut self, c: &Change, e: &LogEntry, it: &ChangeItem) {
        let n = self.node(&item_iri(&it.id), &["prov:Entity", "goap:Item"]);
        {
            let m = self.m(&n);
            entry(m, e);
            set(m, "goap:kind", &it.r#type);
            set(m, "goap:type", &it.target);
            set(m, "goap:status", &it.status);
            let mut label = it.r#type.to_string();
            if !it.target.is_empty() {
                label += &format!(" {}", it.target);
            }
            set(m, "label", &label);
            set_time(m, "prov:generatedAtTime", &it.created_at);
            add(m, "prov:wasGeneratedBy", r(&by(c, &it.execution)));
        }
        let p = self.principal(&e.by, &[]);
        let m = self.m(&n);
        if !p.is_empty() {
            add(m, "prov:wasAttributedTo", r(&p));
        }
        for d in &it.derived_from {
            add(m, "prov:wasDerivedFrom", r(&item_iri(d)));
        }
        for s in &it.supersedes {
            add(m, "prov:wasRevisionOf", r(&item_iri(s)));
        }
        if let Some(d) = &it.decision {
            add(m, "goap:decides", r(&item_iri(&d.item)));
            m.insert("goap:accept".into(), Value::Bool(d.accept));
            set(m, "rdfs:comment", &d.comment);
        }
        if it.r#type == domain::TYPE_TRANSITION {
            // a move of the lifecycle of the change (ADR 0058), influenced by the decision point that gated it
            let d = str_of(&it.data, "decision");
            if !d.is_empty() {
                add(
                    m,
                    "prov:wasInfluencedBy",
                    r(&item_iri(&ItemID::from(d.to_string()))),
                );
            }
        }
        if it.r#type == goap_verify::TYPE_VERIFICATION {
            self.verification(&n, it);
        }
        if it.r#type == goap_risk::TYPE_DEROGATION {
            self.derogation(&n, it);
        }
        if it.r#type == goap_review::KIND_REVIEW {
            self.review(c, &n, it);
        }
        if !it.data.is_empty() {
            self.m(&n)
                .insert("data".into(), Value::Object(it.data.clone()));
        }
    }

    /// review maps a version of a review object (ADR 0080): the entity records the version, and the review itself is an
    /// activity of its author that groups the reviewed events of its entries (goap:partOf, set by the event), started
    /// when opened and ended when submitted.
    fn review(&mut self, c: &Change, n: &str, it: &ChangeItem) {
        let rs = goap_review::reviews(std::slice::from_ref(it));
        let Some(rv) = rs.into_iter().next() else {
            return;
        };
        {
            let m = self.m(n);
            add(m, "@type", json!("goap:ReviewRecord"));
            set(m, "label", &format!("review {} {}", rv.key, rv.status));
        }
        let act = self.node(
            &review_object_iri(&rv.key),
            &["prov:Activity", "goap:ReviewObject"],
        );
        {
            let a = self.m(&act);
            set(a, "label", &format!("review {}", rv.key));
            set(a, "goap:reviewKey", &rv.key);
            set(a, "goap:status", &rv.status); // the last version wins
            set(a, "rdfs:comment", &rv.comment);
            add(a, "goap:partOf", r(&change_iri(&c.id)));
            if !a.contains_key("prov:startedAtTime") {
                set_time(a, "prov:startedAtTime", &it.created_at);
            }
            set_time_opt(a, "prov:endedAtTime", &rv.submitted_at);
        }
        let p = self.principal(&rv.by, &[]);
        if !p.is_empty() {
            add(self.m(&act), "prov:wasAssociatedWith", r(&p));
        }
        add(self.m(n), "goap:reviewOf", r(&review_object_iri(&rv.key)));
        let a = self.m(&act);
        for en in &rv.entries {
            add(
                a,
                "goap:about",
                r(&impact_iri(&ChangeImpactID::from(en.impact.clone()))),
            );
        }
    }

    /// verification maps a state of the verification of an effect (ADR 0075): the entity is a Verification of the
    /// change impacts it covers, attributed to the verifier once the effect is judged.
    fn verification(&mut self, n: &str, it: &ChangeItem) {
        use goap_verify as verify;
        {
            let m = self.m(n);
            add(m, "@type", json!("goap:Verification"));
            set(m, "goap:state", str_of(&it.data, verify::KEY_STATE));
            set(m, "goap:oracle", str_of(&it.data, verify::KEY_ORACLE));
            set(
                m,
                "label",
                &format!("verification {}", str_of(&it.data, verify::KEY_STATE)),
            );
            let mut ids = verify::impacts(it);
            ids.push(str_of(&it.data, verify::KEY_IMPACT).to_string());
            for id in ids {
                if !id.is_empty() {
                    add(
                        m,
                        "prov:wasDerivedFrom",
                        r(&impact_iri(&ChangeImpactID::from(id))),
                    );
                }
            }
        }
        let who = str_of(&it.data, verify::KEY_BY);
        if !who.is_empty() {
            let p = self.principal(who, &[]);
            if !p.is_empty() {
                add(self.m(n), "prov:wasAttributedTo", r(&p));
            }
        }
    }

    /// derogation maps a version of a derogation (ADR 0075 §2): an entity of the rule it waives, of its target and
    /// expiry, attributed to the signatory who answers for it.
    pub(crate) fn derogation(&mut self, n: &str, it: &ChangeItem) {
        {
            let m = self.m(n);
            add(m, "@type", json!("goap:Derogation"));
            set(m, "goap:rule", str_of(&it.data, "rule"));
            set(m, "goap:target", str_of(&it.data, "target"));
            set(m, "goap:expires", str_of(&it.data, "expires"));
            set(m, "goap:derogationStatus", str_of(&it.data, "status"));
            set(
                m,
                "label",
                &format!("derogation {}", str_of(&it.data, "key")),
            );
        }
        let p = self.principal(str_of(&it.data, "signatory"), &[]);
        if !p.is_empty() {
            add(self.m(n), "prov:wasAttributedTo", r(&p));
        }
    }

    /// version is the entity of a node version; typ and key describe the node when known.
    fn version(&mut self, nr: &NodeRef, typ: &str, key: &str) -> String {
        let id = version_iri(nr);
        self.node(&id, &["prov:Entity", "goap:NodeVersion"]);
        set(self.m(&id), "label", &nr.to_string());
        if nr.is_draft() {
            // the node has no version while the change works (ADR 0079): its draft, written as a version at landing
            self.node(&id, &["prov:Entity", "goap:NodeDraft"]);
            set(self.m(&id), "label", &format!("{key} (draft)"));
        }
        add(self.m(&id), "prov:specializationOf", r(&node_iri(&nr.id)));
        let node = self.node(&node_iri(&nr.id), &["prov:Entity", "goap:Node"]);
        let m = self.m(&node);
        set(m, "label", &nr.id);
        set(m, "goap:type", typ);
        set(m, "goap:key", key);
        id
    }

    /// propose: a proposal adds the change impact (State); so does a creation, whose one event is also its first
    /// version (Post): ADR 0077.
    fn propose(&mut self, c: &Change, n: &str, ev: &ImpactEvent, actor: &str) {
        if let Some(s) = &ev.state {
            self.impacts.insert(ev.impact.clone(), s.clone());
            {
                let m = self.m(n);
                set(m, "label", &s.key);
                set(m, "goap:key", &s.key);
                set(m, "goap:type", &s.r#type);
                set(m, "goap:intent", &s.intent);
                set(m, "goap:rationale", &s.rationale);
                for d in &s.derived_from {
                    add(m, "prov:wasDerivedFrom", r(&item_iri(d)));
                }
                for it in &s.items {
                    add(m, "prov:wasDerivedFrom", r(&item_iri(it)));
                }
            }
            if let Some(pre) = &s.pre {
                let v = self.version(pre, &s.r#type, &s.key);
                add(self.m(n), "goap:pre", r(&v));
                let run = self.node(&by(c, &ev.execution), &[]);
                add(self.m(&run), "prov:used", r(&version_iri(pre)));
            }
        }
        let m = self.m(n);
        set_time_opt(m, "prov:generatedAtTime", &ev.at);
        add(m, "prov:wasGeneratedBy", r(&by(c, &ev.execution)));
        if !actor.is_empty() {
            add(m, "prov:wasAttributedTo", r(actor));
        }
    }

    fn type_key(&self, impact: &ChangeImpactID) -> (String, String) {
        self.impacts
            .get(impact)
            .map(|s| (s.r#type.clone(), s.key.clone()))
            .unwrap_or_default()
    }

    /// impact is an event of a change impact (ADR 0029).
    fn impact(&mut self, c: &Change, e: &LogEntry, ev: &ImpactEvent) {
        let actor = self.principal(&ev.by, &[]);
        if ev.op == domain::IMPACT_ADOPTED {
            // change level: a flow branch is adopted, replacing the runs it makes stale (ADR 0025)
            let a = self.node(
                &iri("adoption", &ev.id),
                &["prov:Activity", "goap:Adoption"],
            );
            let m = self.m(&a);
            entry(m, e);
            set(m, "label", &format!("adopt {}", ev.flow));
            set_time_opt(m, "prov:startedAtTime", &ev.at);
            set_time_opt(m, "prov:endedAtTime", &ev.at);
            add(m, "goap:partOf", r(&change_iri(&c.id)));
            if !actor.is_empty() {
                add(m, "prov:wasAssociatedWith", r(&actor));
            }
            for s in &ev.stale {
                add(m, "goap:replaces", r(&run_iri(s)));
            }
            return;
        }
        let imp = impact_iri(&ev.impact);
        self.node(&imp, &["prov:Entity", "goap:ChangeImpact"]);
        {
            let m = self.m(&imp);
            entry(m, e);
            add(m, "goap:change", r(&change_iri(&c.id)));
        }
        let (mut typ, mut key) = self.type_key(&ev.impact);
        let op = &ev.op;
        if *op == domain::IMPACT_PROPOSED {
            self.propose(c, &imp, ev, &actor);
        } else if *op == domain::IMPACT_TRANSITIONED
            || *op == domain::IMPACT_CHECKED_OUT
            || *op == domain::IMPACT_CREATED
        {
            if *op == domain::IMPACT_TRANSITIONED
                && ev.draft.is_none()
                && ev.post.as_ref().is_some_and(NodeRef::is_draft)
            {
                return; // a transition taken on the draft writes no version (ADR 0079): only its entry
            }
            if *op == domain::IMPACT_CREATED {
                self.propose(c, &imp, ev, &actor);
                if self.impacts.contains_key(&ev.impact) {
                    (typ, key) = self.type_key(&ev.impact);
                }
            }
            let Some(post) = &ev.post else { return };
            let v = self.version(post, &typ, &key);
            {
                let m = self.m(&v);
                set_time_opt(m, "prov:generatedAtTime", &ev.at);
                add(m, "prov:wasGeneratedBy", r(&by(c, &ev.execution)));
                if !actor.is_empty() {
                    add(m, "prov:wasAttributedTo", r(&actor));
                }
            }
            if let Some(pre) = self.impacts.get(&ev.impact).and_then(|s| s.pre.clone()) {
                let p = self.version(&pre, &typ, &key);
                add(self.m(&v), "prov:wasRevisionOf", r(&p));
            }
            // a merge or a split derives its new node from the nodes it replaces (ADR 0077)
            for o in origins_of(&ev.patch) {
                let p = self.version(&o.r#ref, &typ, &o.key);
                add(self.m(&v), "prov:wasDerivedFrom", r(&p));
            }
            add(self.m(&imp), "goap:post", r(&version_iri(post)));
            if let Some(s) = self.impacts.get_mut(&ev.impact) {
                s.post = Some(post.clone());
            }
        } else if *op == domain::IMPACT_REVIEWED || *op == domain::IMPACT_DISCARDED {
            // a review is an activity of its reviewer, judging the version written
            let rv = self.node(&iri("review", &ev.id), &["prov:Activity", "goap:Review"]);
            {
                let m = self.m(&rv);
                entry(m, e);
                set(m, "goap:op", &ev.op);
                set_time_opt(m, "prov:startedAtTime", &ev.at);
                set_time_opt(m, "prov:endedAtTime", &ev.at);
                add(m, "goap:partOf", r(&change_iri(&c.id)));
                add(m, "goap:about", r(&imp));
            }
            if let Some(review) = ev.review.as_ref().filter(|r| !r.review_id.is_empty()) {
                // reviewed in a review object (ADR 0080): the object groups the events it submitted and, submitted, is
                // the cause of each verdict (ADR 0105)
                let obj = review_object_iri(&review.review_id);
                add(self.m(&rv), "goap:partOf", r(&obj));
                self.node(&obj, &["prov:Activity", "goap:ReviewObject"]);
                if !e.causation.is_empty() {
                    add(self.m(&rv), "prov:wasInformedBy", r(&obj));
                }
            }
            let post = self.impacts.get(&ev.impact).and_then(|s| s.post.clone());
            let m = self.m(&rv);
            if !actor.is_empty() {
                add(m, "prov:wasAssociatedWith", r(&actor));
            }
            if let Some(review) = &ev.review {
                set(m, "label", &format!("{} {}", ev.op, review.status));
                set(m, "goap:status", &review.status);
                set(m, "rdfs:comment", &review.comment);
            }
            if let Some(post) = post {
                add(m, "prov:used", r(&version_iri(&post)));
            }
        } else if *op == domain::IMPACT_LANDED {
            let Some(landed) = &ev.landed else { return };
            let v = self.version(landed, &typ, &key);
            add(self.m(&imp), "goap:landed", r(&version_iri(landed)));
            let post = self.impacts.get(&ev.impact).and_then(|s| s.post.clone());
            match post {
                Some(p) if p.is_draft() => {
                    // the version is written from the draft when the change lands (ADR 0079)
                    let d = self.version(&p, &typ, &key);
                    let m = self.m(&v);
                    add(m, "prov:wasDerivedFrom", r(&d));
                    add(m, "prov:wasGeneratedBy", r(&by(c, &ev.execution)));
                    set_time_opt(m, "prov:generatedAtTime", &ev.at);
                    if let Some(s) = self.impacts.get_mut(&ev.impact) {
                        s.post = Some(landed.clone());
                    }
                }
                Some(p) if p != *landed => {
                    // a merge version of a node changed on both sides (ADR 0032)
                    let m = self.m(&v);
                    add(m, "prov:wasDerivedFrom", r(&version_iri(&p)));
                    add(m, "prov:wasGeneratedBy", r(&by(c, &ev.execution)));
                    set_time_opt(m, "prov:generatedAtTime", &ev.at);
                }
                _ => {}
            }
            if !ev.baseline.is_empty() {
                // a state the change left: on its own branch when committed, on the target when integrated (ADR 0056)
                let bl = self.node(
                    &baseline_iri(&ev.baseline),
                    &["prov:Entity", "prov:Collection", "goap:Baseline"],
                );
                let m = self.m(&bl);
                add(m, "prov:wasGeneratedBy", r(&change_iri(&c.id)));
                add(m, "prov:hadMember", r(&version_iri(landed)));
            }
        } else if *op == domain::IMPACT_REBASED
            && let Some(pre) = &ev.pre
        {
            let p = self.version(pre, &typ, &key);
            add(self.m(&imp), "goap:rebasedOn", r(&p));
            if let Some(s) = self.impacts.get_mut(&ev.impact) {
                s.pre = Some(pre.clone());
            }
        }
    }
}
